import pandas as pd

def total_baris(w):
    return w.sum(axis=1).to_dict()

import pandas as pd

def toko_terbaik(w):
    return w.idxmax(axis=1).tolist()

import pandas as pd

def porsi_toko(w):
    return w.div(w.sum(axis=1), axis=0).round(3).values.tolist()

import pandas as pd

def perubahan_bulanan(w):
    return w.diff().fillna(0).values.tolist()
